select energy_manager.load_cards($cards$[
{"id":"p4-b13-033","paper":4,"topic":"Cement Industry","kind":"problem","front":"In Example 13.1 kiln heat balance, how many kg of fuel is burned per kg of clinker?","back":"About 0.1218 kg fuel per kg clinker (12.18%). This gives about 741 kcal/kg clinker from coal combustion.","explain":"Fuel mass is the unknown. Heat in equals heat out, and the fuel-dependent terms (sensible heat, fuel moisture and combustion heat) appear on both sides, so solving them together gives the fuel rate.","steps":[{"prompt":"Add the fixed heat outputs for 1 kg clinker, leaving out the fuel-moisture term.","answer":"404.22 + 9.04 + 152.23 + 21.23 + 124.52 + 6.63 + 4.38 + 48.13 = 770.38 kcal/kg clinker.","explain":"Only fixed terms are summed. The fuel-moisture term (6.707 × m_fuel) is kept as a coefficient of the fuel mass."},{"prompt":"Add the fixed heat inputs.","answer":"18.74 + 8.0 + 0.54 + 1.19 = 28.47 kcal/kg clinker.","explain":"Kiln feed sensible heat, cooling air, primary air and leaking air do not depend on the fuel mass."},{"prompt":"Write the fuel-dependent input terms.","answer":"Sensible heat of fuel 13.824 × m + coal combustion 6084 × m = 6097.824 × m kcal/kg clinker.","explain":"Fuel heat scales with fuel mass, so total input = 28.47 + 6097.824 × m."},{"prompt":"Equate total input and total output, and solve for m.","answer":"28.47 + 6097.824 m = 770.38 + 6.707 m, so 6091.117 m = 741.91 and m = 0.1218 kg fuel per kg clinker.","explain":"This is the fuel rate on a clinker basis (12.18%)."},{"prompt":"Compute the heat from coal combustion.","answer":"6084 × 0.1218 = 741.05 kcal/kg clinker. Total input and output both close at about 771 kcal/kg clinker.","explain":"The balance closes, which confirms the inputs and outputs are consistent."}],"flash":false,"source":"BEE Book 4 Ch 13 p272","order":4561},
{"id":"p4-b13-034","paper":4,"topic":"Cement Industry","kind":"problem","front":"Example 13.1: with velocity pressure 16.39 mmWG, gas density 0.623 kg/m³ and duct area 8.299 m², what is the preheater exit gas velocity, and what is its specific volume at kiln output 171.68 TPH?","back":"Velocity 19.17 m/s. Gas flow 159.1 m³/s, about 248,565 Nm³/h, which is 1.45 Nm³ per kg clinker.","explain":"This is the book's own worked calculation. Velocity comes from the Pitot formula; the Nm³ conversion uses the STP density of the gas (1.436 kg/Nm³).","steps":[{"prompt":"Calculate the gas velocity with the Pitot formula (Cp = 0.844).","answer":"V = 0.844 × √(2 × 9.81 × 16.39 / 0.623) = 0.844 × 22.72 = 19.17 m/s.","explain":"Velocity pressure is in mmWG and the density is in kg/m³, consistent with the book."},{"prompt":"Calculate the volume flow.","answer":"Vg = 19.17 × 8.299 = 159.1 m³/s.","explain":"Volume flow = velocity × duct cross-sectional area."},{"prompt":"Convert the flow to Nm³/h.","answer":"Vg = 159.1 × 3600 × (0.623 / 1.436) = 248,565 Nm³/h.","explain":"Multiply by 3600 for hours and by the density ratio to reach standard conditions."},{"prompt":"Divide by the kiln output to get specific volume.","answer":"248,565 / 171,680 = 1.45 Nm³/kg clinker.","explain":"Specific volume is the gas flow per kg of clinker produced."}],"flash":false,"source":"BEE Book 4 Ch 13 p267","order":4562},
{"id":"p4-b13-035","paper":4,"topic":"Cement Industry","kind":"problem","front":"Example 13.1: what is the heat loss in preheater exit gas at 1.45 Nm³/kg clinker, 1.436 kg/Nm³, Cp 0.247 kcal/kg °C and 316 °C exit temperature?","back":"About 152 kcal/kg clinker (book value 152.23).","explain":"Heat loss = mass of gas per kg clinker × specific heat × (gas temperature − 20 °C reference).","steps":[{"prompt":"Find the mass of gas per kg clinker.","answer":"1.45 × 1.436 = 2.08 kg/kg clinker.","explain":"Mass = specific volume (Nm³/kg) × STP density (kg/Nm³)."},{"prompt":"Find the temperature rise above the reference.","answer":"316 − 20 = 296 °C.","explain":"The book uses 20 °C as the reference temperature."},{"prompt":"Compute the heat loss.","answer":"Q = 2.08 × 0.247 × 296 = 152.2 kcal/kg clinker.","explain":"Q = m × Cp × (t − t_ref), the same form used for every exit-gas heat term."}],"flash":false,"source":"BEE Book 4 Ch 13 p267","order":4563},
{"id":"p4-b13-036","paper":4,"topic":"Cement Industry","kind":"problem","front":"Example 13.2: how much hot gas (at 280 °C) is needed to dry the raw mill feed (100 TPH fresh feed, 105 °C dedusting gas, 3095 kW mill power)?","back":"About 74,709 Nm³/h of hot gas.","explain":"Heat output (raw material, dedusting gas, radiation, moisture evaporation, false air) is balanced against heat input (fresh feed, grinding power, false air). The shortfall is supplied by the hot gas.","steps":[{"prompt":"Heat to raw material and to dedusting gas.","answer":"Raw material: 100 × 1000 × 0.21 × (105 − 20 − 5) = 1.68 × 10⁶ kcal/h. Dedusting gas: 150,000 × 0.31 × (105 − 20) × 273/(105 + 273) = 2.855 × 10⁶ kcal/h.","explain":"Raw material is taken as 5 °C below exit gas temperature, as the book notes."},{"prompt":"Radiation loss, moisture evaporation and false air loss.","answer":"Radiation: 185 × 50 × (105 − 20) = 7.86 × 10⁵ kcal/h. Moisture: 6122 × (540 + 105 − 35) = 3.734 × 10⁶ kcal/h. False air: 150,000 × 0.10 × 0.30 × (105 − 20) = 3.83 × 10⁵ kcal/h.","explain":"Moisture evaporated is 6122 kg/h (see the next card)."},{"prompt":"Total heat output.","answer":"1.68 + 2.855 + 0.786 + 3.734 + 0.383 = 9.438 × 10⁶ kcal/h.","explain":"Sum of all heat-output terms."},{"prompt":"Heat input without the hot gas.","answer":"Fresh feed: 100 × 1000 × 0.21 × (35 − 20) = 3.15 × 10⁵. Grinding power: 3095 × 0.94 × 0.98 × 860 = 2.451 × 10⁶. False air: 6.75 × 10⁴. Total 2.834 × 10⁶ kcal/h.","explain":"Ambient air and grinding power are the inputs apart from the hot gas."},{"prompt":"Solve for the hot gas flow.","answer":"Heat from hot gas = 9.438 × 10⁶ − 2.834 × 10⁶ = 6.604 × 10⁶ kcal/h. Gh = 6.604 × 10⁶ / (0.34 × (280 − 20)) = 74,709 Nm³/h.","explain":"The book's answer is 74,709 Nm³/h."}],"flash":false,"source":"BEE Book 4 Ch 13 p274","order":4564},
{"id":"p4-b13-037","paper":4,"topic":"Cement Industry","kind":"problem","front":"In the raw mill example (100 TPH fresh feed, feed moisture 8%, product moisture 2%, exit gas 105 °C, ambient 35 °C), how much water is evaporated per hour, and what heat does that need?","back":"6122 kg/h of water, needing about 3.734 × 10⁶ kcal/h.","explain":"The water evaporated is the feed moisture removed, measured on the wet-basis formula. The latent heat term uses 540 kcal/kg, plus sensible heat up to the exit temperature.","steps":[{"prompt":"Calculate the moisture to evaporate.","answer":"Fq × (Mf − Mp) / (100 − Mp) = 100,000 × (8 − 2) / (100 − 2) = 6122 kg/h.","explain":"Fq is in kg/h, and the formula is on a wet basis."},{"prompt":"Find the heat per kg of water evaporated.","answer":"540 + Egt − Amb = 540 + 105 − 35 = 610 kcal/kg.","explain":"Latent heat of water is 540 kcal/kg; the gas is cooled to ambient in the book's method."},{"prompt":"Compute the heat loss.","answer":"6122 × 610 = 3.734 × 10⁶ kcal/h.","explain":"This is the largest single heat-output term in the example (about 40% of output)."}],"flash":false,"source":"BEE Book 4 Ch 13 p275","order":4565},
{"id":"p4-b13-038","paper":4,"topic":"Cement Industry","kind":"problem","front":"Solved example: with a density of 0.581 kg/m³, velocity pressure 28.6 mmWG and duct area 2.27 m², what is the specific volume of preheater gas at 45.16 TPH clinker, and what is the gas velocity?","back":"Velocity 26.4 m/s. Flow 215,640 m³/h, which is 89,491 Nm³/h, or 1.98 Nm³ per kg clinker.","explain":"This is the book's solved example for the preheater fan inlet. Pitot constant 0.85 is used here, unlike 0.844 in Example 13.1.","steps":[{"prompt":"Find the prevailing gas density at the fan inlet (static −650 mmWC, 316 °C).","answer":"ρ = 1.40 × 273 × (9908 − 650) / ((273 + 316) × 10334) = 0.581 kg/m³.","explain":"9908 mmWC is the plant's standard pressure, adjusted for altitude."},{"prompt":"Calculate the gas velocity.","answer":"V = 0.85 × √(2 × 9.8 × 28.6 / 0.581) = 26.4 m/s.","explain":"Velocity pressure is taken directly from the measured value."},{"prompt":"Calculate the volumetric flow.","answer":"26.4 × 2.27 = 59.9 m³/s = 215,640 m³/h.","explain":"Volume flow = velocity × duct area, converted to m³/h."},{"prompt":"Convert to Nm³/h and find specific volume.","answer":"215,640 × 0.58 / 1.4 = 89,491 Nm³/h. 89,491 / 45,160 = 1.98 Nm³/kg clinker.","explain":"45.16 TPH is 45,160 kg/h of clinker."}],"flash":false,"source":"BEE Book 4 Ch 13 p278","order":4566},
{"id":"p4-b13-039","paper":4,"topic":"Cement Industry","kind":"problem","front":"Solved example: what is the heat loss in preheater exit gas at 1.98 Nm³/kg clinker, density 1.4 kg/Nm³, Cp 0.248 and 316 °C?","back":"About 203.5 kcal/kg clinker.","explain":"Same Q = m × Cp × (t − 20) form. The high specific volume is what makes this loss large.","steps":[{"prompt":"Find mass of gas per kg clinker.","answer":"1.98 × 1.4 = 2.772 kg/kg clinker.","explain":"Specific volume × STP density."},{"prompt":"Compute the heat loss.","answer":"Q = 2.772 × 0.248 × (316 − 20) = 203.5 kcal/kg clinker.","explain":"The book reports the same value."},{"prompt":"Compare with Example 13.1.","answer":"Example 13.1 gives 152 kcal/kg at 1.45 Nm³/kg. This solved example's higher specific volume (1.98 Nm³/kg) gives a larger loss of 203.5 kcal/kg.","explain":"Heat loss in the exit gas is proportional to specific volume, so more gas per kg of clinker means more heat lost."}],"flash":false,"source":"BEE Book 4 Ch 13 p279","order":4567},
{"id":"p4-b13-040","paper":4,"topic":"Cement Industry","kind":"problem","front":"Solved example: if design specific volume of preheater gas is 1.75 Nm³/kg clinker and measured is 1.98, what is the annual monetary loss? Use 23.6 kcal/kg excess heat, NCV 5500 kcal/kg coal, 45.16 TPH, 8000 h/yr and Rs 6500 per tonne.","back":"About 1552 tonnes of coal per year, worth about Rs 100.88 lakh.","explain":"The excess specific volume is converted to heat, then to coal equivalent, then to annual coal and money. The book gives the same answer.","steps":[{"prompt":"Find the excess specific volume and the heat loss.","answer":"Excess = 1.98 − 1.75 = 0.23 Nm³/kg. Heat loss = 0.23 × 1.4 × 0.248 × 296 = 23.6 kcal/kg clinker.","explain":"Same Q = m × Cp × ΔT form, using the excess volume only."},{"prompt":"Convert heat to coal equivalent.","answer":"23.6 / 5500 = 0.0043 kg coal per kg clinker.","explain":"Divide the heat loss by the NCV of coal."},{"prompt":"Coal saving per hour.","answer":"0.0043 × 45.16 = 0.194 TPH.","explain":"Multiply by the clinker production rate."},{"prompt":"Annual coal saving and money.","answer":"0.194 × 8000 = 1552 t/yr. 1552 × 6500 = Rs 100.88 lakh per year.","explain":"Multiply by operating hours, then by coal cost per tonne."}],"flash":false,"source":"BEE Book 4 Ch 13 p279","order":4568},
{"id":"p4-b13-041","paper":4,"topic":"Cement Industry","kind":"problem","front":"Question N-1: with 158 TPH clinker, static pressure −682 mmWC, velocity pressure 18 mmWC, 3000 mm duct, 325 °C gas, Cp 0.243, O₂ 4.0%, CO 0.3% and CO₂ 24.1%, what is the heat in preheater exhaust gas?","back":"About 148 kcal/kg clinker, using about 1.40 Nm³/kg specific volume (worked here from the chapter formulas, not a book answer).","explain":"The book poses this as an exercise without an answer key. The steps follow the chapter's formulas for STP density, prevailing density, velocity and heat. Check your working against the book's method before using this answer in an exam.","steps":[{"prompt":"Find the duct area and the STP density of the gas.","answer":"Area = π × 3.0² / 4 = 7.07 m². STP density = (4.0 × 32 + 24.1 × 44 + 71.9 × 28) / (22.4 × 100) = 1.429 kg/Nm³ (N₂ + CO = 100 − 4.0 − 24.1 = 71.9%).","explain":"The gas analysis is on a dry basis, as the book notes for Example 13.1."},{"prompt":"Find the prevailing density and the velocity.","answer":"ρ = 1.429 × (10334 − 682) / 10334 × 273 / (273 + 325) = 0.609 kg/m³. V = 0.844 × √(2 × 9.81 × 18 / 0.609) = 20.3 m/s.","explain":"Pitot coefficient 0.844 is the value used in Example 13.1."},{"prompt":"Find the gas flow in Nm³/h and the specific volume.","answer":"Flow = 20.3 × 7.07 = 143.6 m³/s = 517,000 m³/h. Nm³/h = 517,000 × 0.609 / 1.429 = 220,460. Specific volume = 220,460 / 158,000 = 1.395 Nm³/kg.","explain":"158 TPH is 158,000 kg/h of clinker."},{"prompt":"Find the mass of gas and the heat in the exit gas.","answer":"m = 1.395 × 1.429 = 1.994 kg/kg clinker. Q = 1.994 × 0.243 × (325 − 20) = 147.8 ≈ 148 kcal/kg clinker.","explain":"Same Q = m × Cp × (t − 20) form as before."}],"flash":false,"source":"BEE Book 4 Ch 13 p280","order":4569},
{"id":"p4-b13-042","paper":4,"topic":"Cement Industry","kind":"problem","front":"Question N-1 (part ii): with the same preheater gas (specific volume 1.395 Nm³/kg clinker, 0.3% CO), what is the heat loss from incomplete combustion?","back":"About 12.6 kcal/kg clinker, from the chapter's CO formula (worked here, not a book answer).","explain":"Incomplete combustion loss depends on the CO share of the exit gas. The heat of combustion of CO is 67,636 kcal per kg-mole.","steps":[{"prompt":"Find the kg-mole of CO per kg clinker.","answer":"CO% × specific volume / (100 × 22.4) = 0.3 × 1.395 / 2240 = 1.87 × 10⁻⁴ kg-mole/kg clinker.","explain":"The 22.4 Nm³ per kg-mole converts volume to moles."},{"prompt":"Find the heat loss.","answer":"Q = 1.87 × 10⁻⁴ × 67,636 = 12.6 kcal/kg clinker.","explain":"Multiply CO moles by the heat of combustion of CO."},{"prompt":"Check the size of the result.","answer":"12.6 kcal/kg is small against the 771 kcal/kg total heat balance, but a CO share of 0.3% still shows incomplete combustion to investigate.","explain":"CO in the exit gas is a direct sign of incomplete combustion, so it should be checked alongside the heat loss."}],"flash":false,"source":"BEE Book 4 Ch 13 p280","order":4570},
{"id":"p4-b13-043","paper":4,"topic":"Cement Industry","kind":"problem","front":"Question L-1: what is the heat of formation of clinker for an analysis of SiO₂ 22.68%, Fe₂O₃ 5.92%, Al₂O₃ 5.29%, CaO 63%, MgO 1.25% (loss-free basis)?","back":"About 382 kcal/kg clinker.","explain":"Heat of formation is a heat-output term in the clinker heat balance. The chapter's formula is ΔH = 2.22 Al₂O₃ + 6.48 MgO + 7.646 CaO − 5.116 SiO₂ − 0.59 Fe₂O₃. The book has no printed answer for this exercise.","steps":[{"prompt":"Compute the Al₂O₃ and MgO terms.","answer":"2.22 × 5.29 = 11.74; 6.48 × 1.25 = 8.10.","explain":"Positive coefficients add heat."},{"prompt":"Compute the CaO term.","answer":"7.646 × 63 = 481.70.","explain":"CaO is the largest contributor."},{"prompt":"Compute the SiO₂ and Fe₂O₃ terms.","answer":"5.116 × 22.68 = 116.03 (subtract); 0.59 × 5.92 = 3.49 (subtract).","explain":"SiO₂ and Fe₂O₃ reduce the heat of formation."},{"prompt":"Sum the terms.","answer":"11.74 + 8.10 + 481.70 − 116.03 − 3.49 = 382.02 kcal/kg clinker.","explain":"Compare with 404 kcal/kg for the book's own example analysis."}],"flash":false,"source":"BEE Book 4 Ch 13 p280","order":4571},
{"id":"p4-b13-044","paper":4,"topic":"Cement Industry","kind":"problem","front":"Question L-2: what is the density of air at 120 °C and a static pressure of −45 mmWC (STP density 1.293 kg/Nm³)?","back":"About 0.894 kg/m³.","explain":"Apply the pressure correction and the temperature correction to the STP density. The formula is the same one used for gas density throughout the chapter.","steps":[{"prompt":"Find the pressure factor.","answer":"(10334 − 45) / 10334 = 0.9956.","explain":"Static pressure is in mmWC; 10334 mmWC is standard atmospheric pressure at sea level."},{"prompt":"Find the temperature factor.","answer":"273 / (273 + 120) = 0.6947.","explain":"Temperature must be in kelvin."},{"prompt":"Compute the density.","answer":"ρ = 1.293 × 0.9956 × 0.6947 = 0.894 kg/m³.","explain":"Air is less dense than at STP because of the higher temperature."}],"flash":false,"source":"BEE Book 4 Ch 13 p280","order":4572},
{"id":"p4-b14-001","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What is the Energy Performance Index (EPI), and what is its unit?","back":"Total annual energy consumption divided by total built-up area, in kWh/annum/m².","explain":"EPI measures how efficiently a building uses energy relative to its size. It does not account for different operating hours, which is why the Average Annual Hourly EPI is also used.","flash":true,"source":"BEE Book 4 Ch 14 p285","order":4573},
{"id":"p4-b14-002","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What counts as built-up area for EPI, and what is excluded?","back":"Carpet area plus area covered by wall thickness, balconies and similar. Parking areas are excluded.","explain":"Energy use is taken from grid and captive sources, and the built-up area is taken for the same building, so the EPI compares like with like.","flash":false,"source":"BEE Book 4 Ch 14 p285","order":4574},
{"id":"p4-b14-003","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"How is AAHEPI calculated from EPI?","back":"AAHEPI (Wh/h/m²) = EPI (kWh/annum/m²) ÷ operating hours per annum × 1000.","explain":"It normalises for actual operating hours, which gives a fairer comparison for buildings that run different hours per year.","flash":false,"source":"BEE Book 4 Ch 14 p286","order":4575},
{"id":"p4-b14-004","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What main functions does the building envelope perform?","back":"It acts as a thermal barrier between inside and outside (walls, roof, foundation). It regulates interior temperatures and so the energy needed for comfort, and its design also sets how much artificial lighting is needed.","explain":"Envelope design, orientation, glazing, sunlight penetration and air infiltration through cracks all affect heat gain.","flash":false,"source":"BEE Book 4 Ch 14 p286","order":4576},
{"id":"p4-b14-005","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"Why should envelope, HVAC and lighting be designed as one system?","back":"Changing one affects the others. Good roof insulation, efficient windows or better air tightness can reduce the HVAC system size, cutting first cost and running cost. An inefficient lighting system adds to the cooling load.","explain":"This is the integrated design principle: the envelope, HVAC and lighting are balanced together rather than specified separately.","flash":false,"source":"BEE Book 4 Ch 14 p287","order":4577},
{"id":"p4-b14-006","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"In cooling mode, why bring in outside air during evening and night hours?","back":"Cool night air chills the building's thermal mass, which reduces the cooling load the next day.","explain":"In heating mode the aim is the reverse: appropriate glazing and shading to increase daytime solar gain.","flash":true,"source":"BEE Book 4 Ch 14 p287","order":4578},
{"id":"p4-b14-007","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"How is a chiller plant assessed for HVAC performance?","back":"Monitor the plant for one day. Log chilled and cooling water temperatures at 0.1 least count, measure flow with an ultrasonic flow meter, and measure power for the compressor, chilled and cooling water pumps and cooling tower or condenser fans at the same time.","explain":"The aim is to find the actual refrigeration load in TR, the actual power drawn, and compare actual kW/TR with design.","flash":false,"source":"BEE Book 4 Ch 14 p288","order":4579},
{"id":"p4-b14-008","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What is the difference between sensible and latent heat gain in a space?","back":"Sensible gain is heat added by conduction, convection or radiation, which raises the space temperature. Latent gain is energy added when moisture enters as vapour from people, processes, or infiltration.","explain":"Latent heat does not raise temperature, but it still adds to the cooling load because the equipment must condense the moisture out of the air.","flash":false,"source":"BEE Book 4 Ch 14 p289","order":4580},
{"id":"p4-b14-009","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What are the U-factor and the thermal resistance R, and how are they related?","back":"U is the heat flow per unit area per unit temperature difference through an assembly including its boundary films, in W/m²·K. R is the reciprocal of U, in m²·K/W.","explain":"R is also used for thermal resistivity, the reciprocal of thermal conductivity. U for a wall is found by adding the layer resistances and taking the inverse.","flash":false,"source":"BEE Book 4 Ch 14 p289","order":4581},
{"id":"p4-b14-010","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"Name the factors that drive sensible cooling load in a building.","back":"Solar gain through the envelope (walls, glazing, skylights, roof, floors), partitions between spaces at different temperatures, ventilation and infiltration, people, equipment and appliances, and lights.","explain":"Sensible gains from people, cooking and some appliances also add latent gain. The total cooling load is the sum of sensible and latent loads.","flash":false,"source":"BEE Book 4 Ch 14 p289","order":4582},
{"id":"p4-b14-011","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What distinguishes external cooling loads from internal cooling loads?","back":"External loads come from outside: sensible loads through opaque walls, roof and floor, through glazing, and through ventilation and infiltration, plus latent infiltration load. Internal loads are generated inside: people, lights, cooking and equipment.","explain":"Knowing whether a building is envelope-load-dominated or interior-load-dominated shows where design and control effort should go.","flash":false,"source":"BEE Book 4 Ch 14 p290","order":4583},
{"id":"p4-b14-012","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What does the cooling load factor (CLF) account for?","back":"The time lag between a heat gain entering the space and that gain becoming cooling load, because surfaces and furnishings absorb and store heat.","explain":"CLF comes from ASHRAE tables. For example, CLF of 0.65 means 35% of the sensible gain is absorbed and 65% is the actual load at that time.","flash":false,"source":"BEE Book 4 Ch 14 p291","order":4584},
{"id":"p4-b14-013","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"Which factor is used for each gain: CLTD, SCL and CLF?","back":"CLTD for conduction through walls, roof, floors and glass. SCL for solar transmission through glass. CLF for internal gains such as lights, people and equipment.","explain":"All three include the time lag of heat storage in the building mass, which is why they are used instead of a plain temperature difference.","flash":false,"source":"BEE Book 4 Ch 14 p291","order":4585},
{"id":"p4-b14-014","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"When is the CLF assumed to equal 1.0?","back":"When the space is not held at constant temperature over 24 hours (system shut off or set back at night), or when lights and equipment run 24 hours.","explain":"If the space is not conditioned continuously, no stored heat is released later, so the instantaneous gain is the load.","flash":true,"source":"BEE Book 4 Ch 14 p291","order":4586},
{"id":"p4-b14-015","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What are the design assumptions behind the ASHRAE CLTD tables used in the example?","back":"Indoor 25.6 °C, maximum outdoor 35 °C, daily range 11.7 °C, 21 July, 40° N latitude and a dark surface.","explain":"Correction factors are needed for other conditions. In the example, wall type 9 has CLTD 12 °C at 17:00, against an actual temperature difference of only 9.4 °C.","flash":false,"source":"BEE Book 4 Ch 14 p293","order":4587},
{"id":"p4-b14-016","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What sensible and latent heat does one person give off in moderately active office work?","back":"About 75 W sensible and 55 W latent, from the ASHRAE table.","explain":"Heat output varies with age, size, gender, clothing and activity. Sensible gain from people is multiplied by the CLF.","flash":true,"source":"BEE Book 4 Ch 14 p296","order":4588},
{"id":"p4-b14-017","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"People enter a space at 8 a.m. and stay 8 hours. What CLF applies at 2 p.m.?","back":"0.91, since 2 p.m. is 6 hours after entry.","explain":"The longer people stay, the less the surfaces can absorb, so more of the sensible gain becomes load.","flash":false,"source":"BEE Book 4 Ch 14 p296","order":4589},
{"id":"p4-b14-018","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What ballast factor is applied to fluorescent lights in the lighting heat gain formula?","back":"1.2 for fluorescent lights, which adds about 20% for ballast heat. Incandescent lights use 1.0.","explain":"Lighting heat gain = watts × ballast factor × CLF. A 120 W fixture adds about 120 W of heat, similar to an average office worker.","flash":true,"source":"BEE Book 4 Ch 14 p297","order":4590},
{"id":"p4-b14-019","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What is the air change method formula for infiltration airflow?","back":"Infiltration airflow (m³/s) = volume of space (m³) × air changes per hour ÷ 3600.","explain":"Air changes per hour come from ASHRAE tables for the construction quality. The example uses 0.3 ACH for average construction kept at positive pressure.","flash":false,"source":"BEE Book 4 Ch 14 p299","order":4591},
{"id":"p4-b14-020","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What are the sensible and latent infiltration equations?","back":"Sensible: Qs = 1210 × airflow × ΔT (°C). Latent: QL = 3010 × airflow × Δhumidity ratio (g/kg dry air).","explain":"1210 and 3010 come from air at standard conditions (21 °C dry air at sea level). They change at other conditions and elevations.","flash":false,"source":"BEE Book 4 Ch 14 p300","order":4592},
{"id":"p4-b14-021","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"Name the three fan heat gains in a supply air system.","back":"Fan motor heat = power input × (1 − motor efficiency). Fan blade heat = power input × (1 − fan efficiency). Duct heat = power input × fan efficiency.","explain":"These system gains add to the coil load. The book excludes them from its worked example.","flash":false,"source":"BEE Book 4 Ch 14 p302","order":4593},
{"id":"p4-b14-022","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What is lighting power density (LPD)?","back":"Total operating lighting load (W) for a region of the building ÷ built-up area (m²) of that region.","explain":"LPD is assessed floor by floor or section by section from the lamp type, wattage and inventory of lamps.","flash":true,"source":"BEE Book 4 Ch 14 p303","order":4594},
{"id":"p4-b14-023","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What is the room index formula for lighting, and what do its terms mean?","back":"RI = (L × W) / (Hm × (L + W)), where L and W are the interior length and width and Hm is the mounting height of the fittings above the working plane.","explain":"Room index sets how many lux measurement points are needed and which target lux/W/m² value applies.","flash":false,"source":"BEE Book 4 Ch 14 p304","order":4595},
{"id":"p4-b14-024","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"How many lux measurement points are needed for a room index of 3 or more?","back":"At least 36. Room index 2 to below 3 needs 25, and 1 to below 2 needs 16.","explain":"The average maintained illuminance is taken as the average of readings at these points, then compared with the target lux/W/m².","flash":false,"source":"BEE Book 4 Ch 14 p304","order":4596},
{"id":"p4-b14-025","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What do ILER values of 0.75 or more, 0.51 to 0.74, and 0.5 or less indicate?","back":"Satisfactory to good; review suggested; urgent action required.","explain":"ILER = actual lux/W/m² ÷ target lux/W/m². The gap between ILER and 1.0 estimates the energy wasted: (1 − ILER) × (watts/1000) × operating hours.","flash":true,"source":"BEE Book 4 Ch 14 p305","order":4597},
{"id":"p4-b14-026","paper":4,"topic":"Buildings & Commercial","kind":"fact","front":"What extra load do outdoor ventilation air and fans add to the space cooling load to get the total coil load?","back":"The load of outdoor air brought in for ventilation, which has sensible and latent parts, plus heat from the system fans.","explain":"Ventilation loads use the same equations as infiltration. The coil must be sized for the total coil cooling load, not just the space load.","flash":false,"source":"BEE Book 4 Ch 14 p301","order":4598}
]$cards$::jsonb);
